!function(){"use strict";function empresaCtrl($scope,mS,tS){$scope.initiload=function(){try{showLoader(),$scope.empresas=[],mS.getData("get","/Empresa/Get?json="+JSON.stringify({})).then(response=>{hideLoader(),console.log(response),"0"!==response.code?"1"===response.code&&($scope.empresas=JSON.parse(response.payload)||[]):console.log(response)})}catch(error){hideLoader(),console.log(error)}},$scope.initiload(),$scope.resultModal=function(result){"object"==typeof result&&this.initiload()},$scope.askToDelete=async function(item){let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:`<small>Esta seguro de eliminar esta Empresa: <b>${item.razonSocial}</b></small>`,confirmButtonText:"Sí, eliminar",showDenyButton:!0,denyButtonText:"No, cancelar"});isConfirmed&&(showLoader(),mS.getData("post","/Empresa/Delete?id="+item.idEmpresa).then(response=>{hideLoader(),"0"!==response.id?"1"===response.id&&(tS.toastr("success",response.message,response.titleSms),$scope.initiload()):tS.toastr("warning",response.message)}))}}app.controller("empresaCtrl",empresaCtrl),empresaCtrl.$inject=["$scope","mainService","toastService"]}(window.angular);